public static void loadWinIO()
{
	try
	{
		Service1.WriteLog("MSIAPService", "Log", "loadWinIO", "loadWinIO start");
		if (pDllWinIO != IntPtr.Zero)
		{
			Service1.WriteLog("MSIAPService", "Log", "loadWinIO", "driver dll had been loaded");
			return;
		}
		string directoryName = Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
		directoryName += "\\KernCoreLib64.dll";
		pDllWinIO = LoadLibrary(directoryName);
		IntPtr procAddress = GetProcAddress(pDllWinIO, "InitializeKernCoreLib");
		IntPtr procAddress2 = GetProcAddress(pDllWinIO, "GetPortVal");
		IntPtr procAddress3 = GetProcAddress(pDllWinIO, "SetPortVal");
		IntPtr procAddress4 = GetProcAddress(pDllWinIO, "GetPhysLong");
		IntPtr procAddress5 = GetProcAddress(pDllWinIO, "SetPhysLong");
		IntPtr procAddress6 = GetProcAddress(pDllWinIO, "ShutdownKernCoreLib");
		initializeWinIo = (InitializeWinIo)Marshal.GetDelegateForFunctionPointer(procAddress, typeof(InitializeWinIo));
		getPortVal = (GetPortVal)Marshal.GetDelegateForFunctionPointer(procAddress2, typeof(GetPortVal));
		setPortVal = (SetPortVal)Marshal.GetDelegateForFunctionPointer(procAddress3, typeof(SetPortVal));
		getPhysLong = (GetPhysLong)Marshal.GetDelegateForFunctionPointer(procAddress4, typeof(GetPhysLong));
		setPhysLong = (SetPhysLong)Marshal.GetDelegateForFunctionPointer(procAddress5, typeof(SetPhysLong));
		shutdownWinIo = (ShutdownWinIo)Marshal.GetDelegateForFunctionPointer(procAddress6, typeof(ShutdownWinIo));
		if (initializeWinIo())
		{
			tryErrorTimes = 0;
			Service1.WriteLog("MSIAPService", "Log", "loadWinIO", "Load driver success");
			return;
		}
		Service1.WriteLog("MSIAPService", "Log", "loadWinIO", "Load driver failed");
		freeWinIO();
		if (tryErrorTimes < 3)
		{
			tryErrorTimes++;
			Thread.Sleep(1000);
			loadWinIO();
		}
		else
		{
			tryErrorTimes = 0;
		}
	}
	catch (Exception ex)
	{
		Service1.WriteLog("MSIAPService", "Exception", "loadWinIO", "loadWinIO exception :" + ex.Message);
	}
}

