private void watcherOC_EventArrived(object sender, EventArrivedEventArgs e)
{
	string text = Registry.GetValue("HKEY_LOCAL_MACHINE\\SOFTWARE\\Wow6432Node\\MSI\\One Dragon Center\\Component\\Base Module\\Scenario", "OC", "").ToString();
