		{
		case 21:
			Registry.SetValue("HKEY_LOCAL_MACHINE\\SOFTWARE\\Wow6432Node\\MSI\\One Dragon Center\\Component\\Base Module\\Scenario", "OC", "0", RegistryValueKind.DWord);
