				{
					Thread_Timer.Interrupt();
					Thread_Timer = null;
				}
			}
			else if (!checkIntel_CPU_Value_timer)
			{
				checkIntel_CPU_Value_timer = true;
				Thread_Timer = new Thread(checkIntel_CPU_Value_timer_Tick);
				Thread_Timer.Start();
			}
			break;
		case 22:
			Registry.SetValue("HKEY_LOCAL_MACHINE\\SOFTWARE\\Wow6432Node\\MSI\\One Dragon Center\\Component\\Base Module\\Scenario", "OC", "0", RegistryValueKind.DWord);
