[SuppressMessage("Microsoft.Design", "CA1062:Validate arguments of public methods", MessageId = "1", Justification = "Suppression makes no sense")]
public bool ProposeChange(List<ClientTuningProposal> proposals, out List<ClientTuningProposalResult> proposalDelta, out bool requiresReboot)
{
	requiresReboot = false;
	proposalDelta = new List<ClientTuningProposalResult>();
	if (proposals == null || proposals.Count == 0)
	{
		return true;
	}
	List<XtuTuningProposal> proposals2 = proposals.Select((ClientTuningProposal clientTuningProposal) => new XtuTuningProposal
	{
		Id = clientTuningProposal.Id,
		Value = clientTuningProposal.Value
	}).ToList();
	bool flag = tuningLibraryConnection.ProposeChange(proposals2, out var proposalDelta2, out requiresReboot);
	if (flag && proposalDelta2 != null)
	{
		proposalDelta = new List<ClientTuningProposalResult>();
		List<ClientTuningControl> availableControls = GetAvailableControls();
		foreach (XtuTuningProposalResult curItem in proposalDelta2)
		{
			Func<ClientTuningControl, bool> predicate = (ClientTuningControl p) =>
			{
				uint id = p.Id;
				XtuTuningProposalResult xtuTuningProposalResult8 = curItem;
				return id == xtuTuningProposalResult8.Id;
			};
			ClientTuningControl clientTuningControl = availableControls.FirstOrDefault(predicate);
			if (clientTuningControl == null)
			{
				XtuTuningProposalResult xtuTuningProposalResult = curItem;
				Log.LogError("Unable to match proposal delta result to available control item for id: " + xtuTuningProposalResult.Id);
			}
			else
			{
				XtuTuningProposalResult xtuTuningProposalResult2 = curItem;
				clientTuningControl.ProposedValue = xtuTuningProposalResult2.Value;
				XtuTuningProposalResult xtuTuningProposalResult3 = curItem;
				clientTuningControl.Enabled = xtuTuningProposalResult3.Enabled;
			}
			List<ClientTuningProposalResult> obj = proposalDelta;
			ClientTuningProposalResult item = default;
			XtuTuningProposalResult xtuTuningProposalResult4 = curItem;
			item.Id = xtuTuningProposalResult4.Id;
			XtuTuningProposalResult xtuTuningProposalResult5 = curItem;
			item.Value = xtuTuningProposalResult5.Value;
			XtuTuningProposalResult xtuTuningProposalResult6 = curItem;
			item.Enabled = xtuTuningProposalResult6.Enabled;
			XtuTuningProposalResult xtuTuningProposalResult7 = curItem;
			item.RebootRequired = xtuTuningProposalResult7.RebootRequired;
			obj.Add(item);
		}
	}
	if (OnProposeChanges != null)
	{
		try
		{
			OnProposeChanges(proposalDelta, requiresReboot);
		}
		catch (Exception ex)
		{
			Log.LogError(ex, "Exception notifying that changes have been proposed");
		}
	}
	return flag;
}

public bool ApplyChanges(bool forceRestart)
{
	bool flag = false;
	try
	{
		flag = tuningLibraryConnection.ApplyChanges(forceRestart, tuningDelay);
		BenchMarkResultReset();
		if (OnApplyChanges != null)
		{
			if (flag)
			{
				OnApplyChanges(ApplyChangeStatus.ACS_Succeeded);
			}
			else
			{
				OnApplyChanges(ApplyChangeStatus.ACS_Invalid);
			}
		}
	}
	catch (Exception ex)
	{
		Log.LogError(ex, "Exception applying changes");
		OnApplyChanges(ApplyChangeStatus.ACS_Failed);
	}
	return flag;
}

public bool Tune(List<ClientTuningProposal> proposals, out bool requiresReboot)
{
	bool flag = ProposeChange(proposals, out var _, out requiresReboot);
	if (flag)
	{
		flag = ApplyChanges(requiresReboot);
	}
	return flag;
}

