public class MainWindow : Window, IComponentConnector
{
	[StructLayout(LayoutKind.Sequential, Pack = 1)]
	public struct GPUInfoStruct
	{
		public int pState;

		public uint CoreClockMin;

		public uint CoreClockMax;

		public uint MemoryClockMin;

		public uint MemoryClockMax;

		public uint GPUOverClocks;

		public uint MemoryOverClocks;

		public uint GPUClock;

		public uint MemoryClock;

		public uint CurrentTemperature;
	}

	public GPUInfoStruct info;

	private int gpu;

	private int memory;

	private bool _contentLoaded;

	[DllImport("GInf.dll")]
	private static extern bool InitialAndGetCurrentG();

	[DllImport("GInf.dll")]
	private static extern bool Unload();

	[DllImport("GInf.dll", CallingConvention = CallingConvention.Cdecl)]
	private static extern bool GetGInfo([MarshalAs(UnmanagedType.Struct)] ref GPUInfoStruct gpuInfoStruct);

	[DllImport("GInf.dll")]
	private static extern bool SetGPUOC(int delta);

	[DllImport("GInf.dll")]
	private static extern bool SetMemoryOC(int delta);

	public MainWindow()
	{
		InitialAndGetCurrentG();
		InitializeComponent();
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		if (commandLineArgs.Length == 3)
		{
			gpu = int.Parse(commandLineArgs[1]);
			memory = int.Parse(commandLineArgs[2]);
		}
		else
		{
			if (commandLineArgs.Length == 1)
			{
				((Window)this).Close();
				return;
			}
			gpu = int.Parse(commandLineArgs[1]);
			memory = int.Parse(commandLineArgs[2]);
			Thread.Sleep(10000);
		}
		((Window)this).ContentRendered += MainWindow_ContentRendered;
	}

	private void MainWindow_ContentRendered(object sender, EventArgs e)
	{
		SetGPUOC(gpu);
		SetMemoryOC(memory);
		((Window)this).Close();
		Unload();
	}
